from __future__ import annotations

import shutil
from pathlib import Path

MARKER_TEXT = (
    "Generated by scripts/sync_package_resources.py. "
    "Do not edit this directory directly.\n"
)
AUTHORITY_RECEIPTS = (
    "saudi-baloot-official-source-verification-20260831.json",
    "saudi-baloot-official-source-verification-20260831-v2.json",
)


def write_marker(path: Path) -> None:
    path.write_text(MARKER_TEXT, encoding="utf-8", newline="\n")


def main() -> None:
    root = Path(__file__).resolve().parents[1]
    target = root / "src/baloot_platform/resources"
    if target.exists():
        shutil.rmtree(target)
    target.mkdir(parents=True)
    for name in ("configs", "schemas", "migrations", "assets"):
        source = root / name
        if source.exists():
            shutil.copytree(source, target / name)
    generated = target / "generated"
    for source in sorted((root / "generated").glob("localization-usage-*.json")):
        generated.mkdir(exist_ok=True)
        shutil.copy2(source, generated / source.name)
    history = root / "generated/localization-history"
    if history.exists():
        generated.mkdir(exist_ok=True)
        shutil.copytree(history, generated / "localization-history")
    release = target / "release"
    release.mkdir()
    for filename in AUTHORITY_RECEIPTS:
        shutil.copy2(root / "release" / filename, release / filename)
    write_marker(target / "GENERATED_FROM_REPOSITORY_ROOT.txt")
    print(target)


if __name__ == "__main__":
    main()
